/**
 * Writers for Opus and Vorbis in Ogg, generated by code. Opus packets are
 * silent CELT packets that decoders accept (20 ms each); Vorbis audio
 * packets are placeholders, because a decodable Vorbis stream needs real
 * codebooks, so the Vorbis fixtures exercise the probe only.
 */
import { oggPage } from "./flac-files.js";

const text = (s: string) => [...s].map((c) => c.charCodeAt(0));
const u16le = (v: number) => [v & 0xff, (v >> 8) & 0xff];
const u32le = (v: number) => [v & 0xff, (v >>> 8) & 0xff, (v >>> 16) & 0xff, (v >>> 24) & 0xff];

/** A silent 20 ms CELT packet: mono (TOC 0xF8) or stereo (0xFC). */
const silentOpus = (channels: number) => [channels === 1 ? 0xf8 : 0xfc, 0xff, 0xfe];

export interface OpusOptions {
  readonly channels?: 1 | 2;
  readonly packets: number;
  readonly preSkip?: number;
  /** The last page's granule position, instead of the real one. */
  readonly lastGranule?: number;
  /** Packets to put instead of the silent ones, such as crafted TOC bytes. */
  readonly customPackets?: readonly number[][];
  readonly mappingFamily?: number;
}

export function oggOpusFile(options: OpusOptions): Uint8Array<ArrayBuffer> {
  const channels = options.channels ?? 2;
  const preSkip = options.preSkip ?? 312;
  const serial = 0x0905;
  const head = [
    ...text("OpusHead"),
    1,
    channels,
    ...u16le(preSkip),
    ...u32le(48_000),
    ...u16le(0),
    options.mappingFamily ?? 0,
  ];
  const tags = [...text("OpusTags"), ...u32le(6), ...text("fixtur"), ...u32le(0)];
  const pages = [
    oggPage([head], { serial, sequence: 0, granule: 0, type: 0x02 }),
    oggPage([tags], { serial, sequence: 1, granule: 0, type: 0 }),
  ];
  const packets =
    options.customPackets ?? Array.from({ length: options.packets }, () => silentOpus(channels));
  // Ten packets a page, as encoders group them.
  for (let start = 0, page = 2; start < packets.length; start += 10, page += 1) {
    const group = packets.slice(start, start + 10);
    const last = start + 10 >= packets.length;
    const granule =
      last && options.lastGranule !== undefined
        ? options.lastGranule
        : Math.min(packets.length, start + 10) * 960; // decoded samples, pre-skip included
    pages.push(oggPage(group, { serial, sequence: page, granule, type: last ? 0x04 : 0 }));
  }
  return Uint8Array.from(pages.flat());
}

export interface VorbisOptions {
  readonly channels?: number;
  readonly sampleRate?: number;
  /** Block size exponents: small and large, 6–13. */
  readonly blocksizes?: readonly [number, number];
  readonly packets: number;
  readonly lastGranule?: number;
  /** Leave out the setup header. */
  readonly withoutSetup?: boolean;
}

export function oggVorbisFile(options: VorbisOptions): Uint8Array<ArrayBuffer> {
  const [small, large] = options.blocksizes ?? [8, 11];
  const serial = 0x0b0b;
  const id = [
    0x01,
    ...text("vorbis"),
    ...u32le(0),
    options.channels ?? 2,
    ...u32le(options.sampleRate ?? 44_100),
    ...u32le(0),
    ...u32le(128_000),
    ...u32le(0),
    (large << 4) | small,
    0x01,
  ];
  const comment = [0x03, ...text("vorbis"), ...u32le(0), ...u32le(0), 0x01];
  const setup = [0x05, ...text("vorbis"), ...new Array(40).fill(0x2a)];
  const audio = Array.from({ length: options.packets }, () => [0x00, ...new Array(30).fill(0x11)]);
  const pages = [
    oggPage([id], { serial, sequence: 0, granule: 0, type: 0x02 }),
    oggPage(options.withoutSetup ? [comment] : [comment, setup], {
      serial,
      sequence: 1,
      granule: 0,
      type: 0,
    }),
  ];
  const perPacket = 2 ** large / 2;
  for (let start = 0, page = 2; start < audio.length; start += 10, page += 1) {
    const last = start + 10 >= audio.length;
    const granule =
      last && options.lastGranule !== undefined
        ? options.lastGranule
        : Math.min(audio.length, start + 10) * (perPacket / 2);
    pages.push(
      oggPage(audio.slice(start, start + 10), {
        serial,
        sequence: page,
        granule,
        type: last ? 0x04 : 0,
      }),
    );
  }
  return Uint8Array.from(pages.flat());
}
